3	import java.util.List;
4	import net.officefloor.web.HttpPathParameter;
5	import net.officefloor.web.ObjectResponse;
6	
7	/**
8	 * GET /api/clients/{clientId}/projects — every project belonging to one client, oldest id first.
9	 * Wired by {@code officefloor/rest/api/clients/{clientId}/projects.GET.yml}.
10	 */
11	public class ClientProjectsGet {
12	
13	    public void service(@HttpPathParameter("clientId") String clientId,
14	            ProjectRepository projects, ObjectResponse<List<ProjectView>> response) {
